import { isAbsolute, join, resolve } from "node:path";
import {
	type JsonlSessionCreateOptions,
	type JsonlSessionListOptions,
	type JsonlSessionMetadata,
	JsonlSessionRepository,
	type Session,
	type SessionCreateOptions,
	type SessionMetadata,
	type SessionRepository,
} from "@earendil-works/pi-agent-core";
import { NodeExecutionEnv } from "@earendil-works/pi-agent-core/node";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { ModelMetadata, ModelRef, SessionSummary, ThinkingLevel } from "@earendil-works/pi-protocol";
import {
	type CreateSessionOptions,
	PiServerError,
	type PiSessionBackend,
	type PiSessionRuntime,
} from "@earendil-works/pi-server";
import { getAgentDir } from "../config.ts";
import { ModelRuntime } from "../core/model-runtime.ts";
import { SettingsManager } from "../core/settings-manager.ts";
import { toPiServerError } from "./errors.ts";
import { ServerModelResolver } from "./model-resolver.ts";
import { type SessionLease, SessionLockManager } from "./session-lock.ts";
import { CodingAgentSessionRuntime } from "./session-runtime.ts";
import { initializeServerSession, inspectServerSession } from "./session-state.ts";

const DEFAULT_SESSION_ROOT_NAME = "server-sessions";
const DEFAULT_LOCK_ROOT_NAME = "server-session-locks";

export interface CodingAgentServerBackendOptions {
	agentDir?: string;
	sessionRoot?: string;
	lockRoot?: string;
	defaultCwd?: string;
	modelRuntime?: ModelRuntime;
	settingsManager?: SettingsManager;
}

export interface CodingAgentServerRepositoryOptions<
	TMetadata extends SessionMetadata,
	TCreateOptions extends SessionCreateOptions,
	TListOptions,
> extends Omit<CodingAgentServerBackendOptions, "sessionRoot"> {
	sessionRepository: SessionRepository<TMetadata, TCreateOptions, TListOptions>;
	createSessionOptions(options: { id: string; cwd: string }): TCreateOptions;
}

export class CodingAgentServerBackend<
	TMetadata extends SessionMetadata = JsonlSessionMetadata,
	TCreateOptions extends SessionCreateOptions = JsonlSessionCreateOptions,
	TListOptions = JsonlSessionListOptions,
> implements PiSessionBackend
{
	private readonly modelRuntime: ModelRuntime;
	private readonly settingsManager: SettingsManager;
	private readonly defaultCwd: string;
	private readonly modelResolver: ServerModelResolver;
	private readonly sessions: SessionRepository<TMetadata, TCreateOptions, TListOptions>;
	private readonly createSessionOptions: (options: { id: string; cwd: string }) => TCreateOptions;
	private readonly locks: SessionLockManager;

	private constructor(options: {
		modelRuntime: ModelRuntime;
		settingsManager: SettingsManager;
		sessions: SessionRepository<TMetadata, TCreateOptions, TListOptions>;
		createSessionOptions(options: { id: string; cwd: string }): TCreateOptions;
		lockRoot: string;
		defaultCwd: string;
	}) {
		this.modelRuntime = options.modelRuntime;
		this.settingsManager = options.settingsManager;
		this.defaultCwd = options.defaultCwd;
		this.modelResolver = new ServerModelResolver(this.modelRuntime, this.settingsManager);
		this.sessions = options.sessions;
		this.createSessionOptions = options.createSessionOptions;
		this.locks = new SessionLockManager(options.lockRoot);
	}

	static create<TMetadata extends SessionMetadata, TCreateOptions extends SessionCreateOptions, TListOptions>(
		options: CodingAgentServerRepositoryOptions<TMetadata, TCreateOptions, TListOptions>,
	): Promise<CodingAgentServerBackend<TMetadata, TCreateOptions, TListOptions>>;
	static create(options?: CodingAgentServerBackendOptions): Promise<CodingAgentServerBackend>;
	static async create<TMetadata extends SessionMetadata, TCreateOptions extends SessionCreateOptions, TListOptions>(
		options:
			| CodingAgentServerBackendOptions
			| CodingAgentServerRepositoryOptions<TMetadata, TCreateOptions, TListOptions> = {},
	): Promise<CodingAgentServerBackend | CodingAgentServerBackend<TMetadata, TCreateOptions, TListOptions>> {
		const agentDir = resolve(options.agentDir ?? getAgentDir());
		const defaultCwd = resolve(options.defaultCwd ?? process.cwd());
		const settingsSource =
			options.settingsManager ?? SettingsManager.create(defaultCwd, agentDir, { projectTrusted: false });
		const settingsManager = SettingsManager.inMemory(settingsSource.getGlobalSettings(), { projectTrusted: false });
		const modelRuntime =
			options.modelRuntime ??
			(await ModelRuntime.create({
				authPath: join(agentDir, "auth.json"),
				modelsPath: join(agentDir, "models.json"),
				allowModelNetwork: false,
			}));
		await modelRuntime.getAvailable();
		await validateCwd(defaultCwd);

		if ("sessionRepository" in options) {
			const backend = new CodingAgentServerBackend<TMetadata, TCreateOptions, TListOptions>({
				modelRuntime,
				settingsManager,
				sessions: options.sessionRepository,
				createSessionOptions: options.createSessionOptions,
				lockRoot: resolve(options.lockRoot ?? join(agentDir, DEFAULT_LOCK_ROOT_NAME)),
				defaultCwd,
			});
			await backend.locks.initialize();
			return backend;
		}

		const sessionRoot = resolve(options.sessionRoot ?? join(agentDir, DEFAULT_SESSION_ROOT_NAME));
		const sessions = new JsonlSessionRepository({
			fs: new NodeExecutionEnv({ cwd: defaultCwd }),
			sessionsRoot: sessionRoot,
		});
		const backend = new CodingAgentServerBackend({
			modelRuntime,
			settingsManager,
			sessions,
			createSessionOptions: ({ id, cwd }) => ({ id, cwd }),
			lockRoot: resolve(options.lockRoot ?? sessionRoot),
			defaultCwd,
		});
		await backend.locks.initialize();
		return backend;
	}

	setDefaultSessionOptions(options: { model?: ModelRef; thinkingLevel?: ThinkingLevel }): void {
		this.modelResolver.setDefaults(options);
	}

	listModels(): Promise<ModelMetadata[]> {
		return this.modelResolver.list();
	}

	async listSessions(): Promise<SessionSummary[]> {
		const catalogLease = await this.locks.acquireCatalog();
		try {
			const stored = await this.sessions.list();
			return await Promise.all(
				stored.map(async (metadata) => {
					try {
						const session = await this.sessions.open(metadata);
						const { state, createdAt } = await inspectServerSession(session);
						if (!state.cwd) throw new Error("stored session has no cwd");
						if (!state.model) throw new Error("stored session has no model");
						if (state.invalidThinkingLevel !== undefined) {
							throw new Error(`stored session has invalid thinking level: ${state.invalidThinkingLevel}`);
						}
						return {
							id: metadata.id,
							name: state.name,
							cwd: state.cwd,
							createdAt,
							updatedAt: state.updatedAt,
							phase: "idle" as const,
							model: state.model,
							thinkingLevel: state.thinkingLevel ?? "off",
							attached: false,
							locked: await this.locks.isLocked(metadata.id),
						};
					} catch (error) {
						throw new Error(`Failed to read coding-agent session ${metadata.id}`, { cause: error });
					}
				}),
			);
		} finally {
			await catalogLease.release();
		}
	}

	async createSession(options: CreateSessionOptions): Promise<PiSessionRuntime> {
		const cwd = options.cwd ?? this.defaultCwd;
		await validateCwd(cwd);
		const model = await this.modelResolver.resolve(options.model);
		const thinkingLevel = this.modelResolver.resolveThinkingLevel(model, options.thinkingLevel);
		const catalogLease = await this.locks.acquireCatalog();
		let lease: SessionLease | undefined;
		let session: Session<TMetadata> | undefined;
		let runtime: CodingAgentSessionRuntime | undefined;
		try {
			lease = await this.locks.acquire(options.id);
			if ((await this.sessions.list()).some((metadata) => metadata.id === options.id)) {
				throw new PiServerError("invalid_request", `Session already exists: ${options.id}`);
			}
			session = await this.sessions.create(this.createSessionOptions({ cwd, id: options.id }));
			await initializeServerSession(session, cwd);
			await session.appendModelChange(model.provider, model.id);
			await session.appendThinkingLevelChange(thinkingLevel);
			if (options.name !== undefined) await session.appendSessionName(options.name);
			runtime = await this.createRuntime(session, model, thinkingLevel, lease, cwd);
			await catalogLease.release();
			return runtime;
		} catch (error) {
			const cleanupErrors: unknown[] = [];
			if (runtime) {
				try {
					await runtime.dispose();
				} catch (cleanupError) {
					cleanupErrors.push(cleanupError);
				}
			}
			if (session) {
				try {
					await this.sessions.delete(await session.getMetadata());
				} catch (cleanupError) {
					cleanupErrors.push(cleanupError);
				}
			}
			if (lease) {
				try {
					await lease.release();
				} catch (cleanupError) {
					cleanupErrors.push(cleanupError);
				}
			}
			try {
				await catalogLease.release();
			} catch (cleanupError) {
				cleanupErrors.push(cleanupError);
			}
			if (cleanupErrors.length > 0) {
				throw new AggregateError([error, ...cleanupErrors], `Failed to create and clean up session ${options.id}`);
			}
			throw toPiServerError(error);
		}
	}

	async openSession(sessionId: string): Promise<PiSessionRuntime> {
		const metadata = (await this.sessions.list()).find((candidate) => candidate.id === sessionId);
		if (!metadata) throw new PiServerError("not_found", `Session was not found: ${sessionId}`);
		const lease = await this.locks.acquire(sessionId);
		try {
			const session = await this.sessions.open(metadata);
			const { state } = await inspectServerSession(session);
			if (!state.cwd) throw new PiServerError("invalid_request", `Session ${sessionId} has no saved cwd`);
			await validateCwd(state.cwd);
			if (!state.model) throw new PiServerError("invalid_request", `Session ${sessionId} has no saved model`);
			if (state.invalidThinkingLevel !== undefined) {
				throw new PiServerError(
					"invalid_request",
					`Session ${sessionId} has invalid thinking level: ${state.invalidThinkingLevel}`,
				);
			}
			const model = await this.modelResolver.resolve(state.model);
			const thinkingLevel = this.modelResolver.recoverThinkingLevel(model, state.thinkingLevel);
			if (state.thinkingLevel !== thinkingLevel) await session.appendThinkingLevelChange(thinkingLevel);
			return await this.createRuntime(session, model, thinkingLevel, lease, state.cwd);
		} catch (error) {
			await lease.release();
			throw toPiServerError(error);
		}
	}

	private async createRuntime(
		session: Session<TMetadata>,
		model: Model<Api>,
		thinkingLevel: ThinkingLevel,
		lease: SessionLease,
		cwd: string,
	): Promise<CodingAgentSessionRuntime> {
		return CodingAgentSessionRuntime.create({
			session,
			modelRuntime: this.modelRuntime,
			modelResolver: this.modelResolver,
			settingsManager: this.settingsManager,
			model,
			thinkingLevel,
			lease,
			cwd,
		});
	}
}

async function validateCwd(cwd: string): Promise<void> {
	if (!isAbsolute(cwd)) throw new PiServerError("invalid_request", `Session cwd must be absolute: ${cwd}`);
	const env = new NodeExecutionEnv({ cwd });
	try {
		const canonical = await env.canonicalPath(cwd);
		if (!canonical.ok) {
			throw new PiServerError("invalid_request", `Invalid session cwd ${cwd}: ${canonical.error.message}`);
		}
		const info = await env.fileInfo(canonical.value);
		if (!info.ok || info.value.kind !== "directory") {
			const suffix = info.ok ? "is not a directory" : info.error.message;
			throw new PiServerError("invalid_request", `Invalid session cwd ${cwd}: ${suffix}`);
		}
	} finally {
		await env.cleanup();
	}
}

export { toPiServerError } from "./errors.ts";

import { type AgentHarness, type ExecutionToolContext, type Session, toError } from "@earendil-works/pi-agent-core";
import { NodeExecutionEnv } from "@earendil-works/pi-agent-core/node";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { ModelRef, SessionPhase, SessionSnapshot, ThinkingLevel } from "@earendil-works/pi-protocol";
import {
	PiServerError,
	type PiSessionRuntime,
	type PiSessionRuntimeEvent,
	type PromptInput,
	type SteerInput,
} from "@earendil-works/pi-server";
import type { ModelRuntime } from "../core/model-runtime.ts";
import type { SettingsManager } from "../core/settings-manager.ts";
import { createServerHarness } from "./create-harness.ts";
import { toPiServerError } from "./errors.ts";
import type { ServerModelResolver } from "./model-resolver.ts";
import type { SessionLease } from "./session-lock.ts";
import { inspectServerSession } from "./session-state.ts";
import { LiveTranscript } from "./transcript/live.ts";
import { projectBranchTranscript } from "./transcript/projection.ts";

export interface CreateCodingAgentSessionRuntimeOptions {
	session: Session;
	modelRuntime: ModelRuntime;
	modelResolver: ServerModelResolver;
	settingsManager: SettingsManager;
	model: Model<Api>;
	thinkingLevel: ThinkingLevel;
	lease: SessionLease;
	cwd: string;
}

function throwDisposalErrors(errors: Error[]): void {
	if (errors.length === 0) return;
	if (errors.length === 1) throw errors[0];
	throw new AggregateError(errors, "Session runtime disposal failed");
}

export class CodingAgentSessionRuntime implements PiSessionRuntime {
	private readonly session: Session;
	private readonly modelRuntime: ModelRuntime;
	private readonly modelResolver: ServerModelResolver;
	private readonly env: NodeExecutionEnv;
	private readonly lease: SessionLease;
	private readonly harness: AgentHarness<ExecutionToolContext>;
	private readonly liveTranscript = new LiveTranscript();
	private readonly unsubscribeHarness: () => void;
	private readonly unsubscribeLockCompromise: () => void;
	private lockCompromise?: Error;
	private terminalError?: PiServerError;
	private mutationInFlight = false;
	private phase: SessionPhase = "idle";
	private disposed = false;
	private disposePromise?: Promise<void>;

	private constructor(options: CreateCodingAgentSessionRuntimeOptions, env: NodeExecutionEnv) {
		this.session = options.session;
		this.modelRuntime = options.modelRuntime;
		this.modelResolver = options.modelResolver;
		this.env = env;
		this.lease = options.lease;
		const retry = options.settingsManager.getProviderRetrySettings();
		const idleTimeoutMs = options.settingsManager.getHttpIdleTimeoutMs();
		this.harness = createServerHarness({
			session: this.session,
			modelRuntime: this.modelRuntime,
			settingsManager: options.settingsManager,
			model: options.model,
			thinkingLevel: options.thinkingLevel,
			env: this.env,
			streamOptions: {
				transport: options.settingsManager.getTransport(),
				timeoutMs: retry.timeoutMs ?? (idleTimeoutMs === 0 ? 2_147_483_647 : idleTimeoutMs),
				maxRetries: retry.maxRetries,
				maxRetryDelayMs: retry.maxRetryDelayMs,
			},
			assertUsable: () => this.assertUsable(),
		});
		this.unsubscribeHarness = this.harness.subscribe((event) => {
			try {
				this.liveTranscript.handle(event);
			} catch (error) {
				this.handleProjectionFailure(error);
			}
		});
		this.unsubscribeLockCompromise = this.lease.onCompromised((error) => this.handleLockCompromise(error));
	}

	static create(options: CreateCodingAgentSessionRuntimeOptions): CodingAgentSessionRuntime {
		const env = new NodeExecutionEnv({ cwd: options.cwd, shellPath: options.settingsManager.getShellPath() });
		return new CodingAgentSessionRuntime(options, env);
	}

	getPhase(): SessionPhase {
		return this.phase;
	}

	async snapshot(): Promise<SessionSnapshot> {
		this.assertUsable();
		const metadata = await this.session.getMetadata();
		const { branch, state, createdAt } = await inspectServerSession(this.session);
		if (!state.cwd) throw new PiServerError("invalid_request", "Session has no saved cwd");
		const queuedSteer = this.liveTranscript.queuedSteer;
		return {
			id: metadata.id,
			name: state.name,
			cwd: state.cwd,
			createdAt,
			updatedAt: state.updatedAt,
			phase: this.getPhase(),
			model: { provider: this.harness.getModel().provider, id: this.harness.getModel().id },
			thinkingLevel: this.harness.getThinkingLevel(),
			attached: false,
			locked: true,
			revision: this.liveTranscript.revision,
			transcript: this.liveTranscript.mergeTranscript(projectBranchTranscript(branch)),
			queuedSteer,
			queuedSteerCount: queuedSteer.length,
		};
	}

	async prompt(input: PromptInput): Promise<void> {
		this.assertIdle("prompt");
		this.phase = "turn";
		try {
			await this.harness.prompt(input.text);
			this.assertUsable();
		} catch (error) {
			this.assertUsable();
			throw toPiServerError(error);
		} finally {
			if (!this.lockCompromise) this.phase = "idle";
		}
	}

	async steer(input: SteerInput): Promise<void> {
		this.assertUsable();
		if (this.getPhase() !== "turn") throw new PiServerError("busy", "Session is not accepting steering input");
		try {
			await this.harness.steer(input.text);
			this.assertUsable();
		} catch (error) {
			this.assertUsable();
			throw toPiServerError(error);
		}
	}

	async abort(): Promise<void> {
		this.assertUsable();
		if (this.mutationInFlight) throw new PiServerError("busy", "Cannot abort while session is being updated");
		try {
			await this.harness.abort();
			this.assertUsable();
		} catch (error) {
			this.assertUsable();
			throw toPiServerError(error);
		}
	}

	async setModel(reference: ModelRef): Promise<void> {
		await this.runExclusiveMutation("set model", () => {
			const model = this.modelResolver.resolveAvailable(reference);
			return async () => {
				await this.harness.setModel(model);
				const current = this.harness.getThinkingLevel();
				const clamped = this.modelResolver.recoverThinkingLevel(model, current);
				if (clamped !== current) await this.harness.setThinkingLevel(clamped);
			};
		});
	}

	async setThinking(thinkingLevel: ThinkingLevel): Promise<void> {
		await this.runExclusiveMutation("set thinking", () => {
			const model = this.harness.getModel();
			this.modelResolver.resolveThinkingLevel(model, thinkingLevel);
			return () => this.harness.setThinkingLevel(thinkingLevel);
		});
	}

	subscribe(listener: (event: PiSessionRuntimeEvent) => void): () => void {
		return this.liveTranscript.subscribe(listener);
	}

	async dispose(): Promise<void> {
		if (this.disposePromise) return this.disposePromise;
		this.disposed = true;
		const current = (async () => {
			this.unsubscribeHarness();
			this.unsubscribeLockCompromise();
			this.liveTranscript.clear();
			const errors: Error[] = [];
			// Terminal paths already requested harness shutdown; calling abort again would only report invalid_state.
			if (this.getPhase() !== "idle" && !this.terminalError && !this.lockCompromise) {
				try {
					await this.harness.abort();
				} catch (error) {
					// Abort can fail through harness hooks. Still verify that active work actually settled before releasing ownership.
					errors.push(toError(error));
				}
			}
			try {
				await this.harness.waitForIdle();
			} catch (error) {
				errors.push(toError(error));
				// An unverified shutdown retains the session lease so a retry cannot overlap active work.
				throwDisposalErrors(errors);
			}
			await this.env.cleanup();
			try {
				await this.lease.release();
			} catch (error) {
				errors.push(toError(error));
			}
			throwDisposalErrors(errors);
		})();
		this.disposePromise = current;
		try {
			await current;
		} catch (error) {
			if (this.disposePromise === current) this.disposePromise = undefined;
			throw error;
		}
	}

	private assertUsable(): void {
		if (this.terminalError) throw this.terminalError;
		this.throwIfLockCompromised();
		if (this.disposed) throw new PiServerError("invalid_request", "Session runtime is disposed");
	}

	private throwIfLockCompromised(): void {
		const compromised = this.lockCompromise ?? this.lease.compromisedError();
		if (compromised) {
			throw new PiServerError("session_locked", `Session lock was compromised: ${compromised.message}`);
		}
	}

	private handleLockCompromise(error: Error): void {
		if (this.lockCompromise) return;
		this.lockCompromise = error;
		this.terminateHarness(new PiServerError("session_locked", `Session lock was compromised: ${error.message}`));
	}

	private handleProjectionFailure(error: unknown): void {
		if (this.terminalError) return;
		this.terminalError = new PiServerError("invalid_request", "Session protocol projection failed");
		this.terminalError.cause = error instanceof Error ? error : new Error(String(error));
		this.terminateHarness(this.terminalError);
	}

	private terminateHarness(error: PiServerError): void {
		this.unsubscribeHarness();
		this.harness.requestShutdown({ discardPendingWrites: true });
		this.liveTranscript.emit({ type: "error", error });
	}

	private assertIdle(operation: string): void {
		this.assertUsable();
		if (this.mutationInFlight || this.getPhase() !== "idle") {
			throw new PiServerError("busy", `Cannot ${operation} while session is busy`);
		}
	}

	private async runExclusiveMutation(operation: string, prepare: () => () => Promise<void>): Promise<void> {
		this.assertIdle(operation);
		const mutation = prepare();
		this.mutationInFlight = true;
		try {
			await mutation();
			this.assertUsable();
		} catch (error) {
			if (this.terminalError || this.lockCompromise || this.lease.compromisedError() || this.disposed) {
				this.assertUsable();
			}
			this.terminalError = new PiServerError("invalid_request", `Session failed to ${operation}`);
			this.terminalError.cause = toPiServerError(error);
			this.terminateHarness(this.terminalError);
			throw this.terminalError;
		} finally {
			this.mutationInFlight = false;
		}
	}
}

import { createHash } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { PiServerError } from "@earendil-works/pi-server";
import lockfile, { type LockOptions } from "proper-lockfile";

const STALE_MS = 30_000;
const UPDATE_MS = 10_000;

export interface SessionLease {
	compromisedError(): Error | undefined;
	onCompromised(listener: (error: Error) => void): () => void;
	release(): Promise<void>;
}

function errorCode(error: unknown): string | undefined {
	return typeof error === "object" && error !== null && "code" in error
		? String((error as { code?: unknown }).code)
		: undefined;
}

export class SessionLockManager {
	private readonly root: string;

	constructor(sessionRoot: string) {
		this.root = join(sessionRoot, ".locks");
	}

	async initialize(): Promise<void> {
		await mkdir(this.root, { recursive: true, mode: 0o700 });
	}

	async isLocked(sessionId: string): Promise<boolean> {
		return lockfile.check(await this.ensureTarget(`session:${sessionId}`), { realpath: false, stale: STALE_MS });
	}

	async acquire(sessionId: string): Promise<SessionLease> {
		return this.acquireTarget(`session:${sessionId}`, `Session is locked: ${sessionId}`, 0);
	}

	async acquireCatalog(): Promise<SessionLease> {
		return this.acquireTarget("catalog", "Session catalog is locked", {
			forever: true,
			factor: 1,
			minTimeout: 10,
			maxTimeout: 100,
			randomize: false,
		});
	}

	private async acquireTarget(
		key: string,
		lockedMessage: string,
		retries: NonNullable<LockOptions["retries"]>,
	): Promise<SessionLease> {
		const target = await this.ensureTarget(key);
		let compromised: Error | undefined;
		const listeners = new Set<(error: Error) => void>();
		let releaseLock: (() => Promise<void>) | undefined;
		try {
			releaseLock = await lockfile.lock(target, {
				realpath: false,
				stale: STALE_MS,
				update: UPDATE_MS,
				retries,
				onCompromised: (error) => {
					compromised = error;
					for (const listener of listeners) listener(error);
				},
			});
		} catch (error) {
			if (errorCode(error) === "ELOCKED") {
				throw new PiServerError("session_locked", lockedMessage);
			}
			throw error;
		}
		return this.createLease(
			() => releaseLock?.(),
			listeners,
			() => compromised,
		);
	}

	private async ensureTarget(sessionId: string): Promise<string> {
		await this.initialize();
		const digest = createHash("sha256").update(sessionId, "utf8").digest("hex");
		const target = join(this.root, digest);
		await writeFile(target, "", { flag: "a", mode: 0o600 });
		return target;
	}

	private createLease(
		releaseLock: () => Promise<void> | undefined,
		listeners: Set<(error: Error) => void>,
		getCompromised: () => Error | undefined,
	): SessionLease {
		let released = false;
		let releasing: Promise<void> | undefined;
		return {
			compromisedError: getCompromised,
			onCompromised: (listener) => {
				listeners.add(listener);
				const compromised = getCompromised();
				if (compromised) listener(compromised);
				return () => listeners.delete(listener);
			},
			release: async () => {
				if (released) return;
				if (getCompromised()) {
					released = true;
					listeners.clear();
					return;
				}
				if (releasing) return releasing;
				const current = (async () => {
					await releaseLock();
					released = true;
					listeners.clear();
				})();
				releasing = current;
				try {
					await current;
				} finally {
					if (!released && releasing === current) releasing = undefined;
				}
			},
		};
	}
}

import type { Session, SessionTreeEntry } from "@earendil-works/pi-agent-core";
import { type ThinkingLevel, ThinkingLevelSchema } from "@earendil-works/pi-protocol";
import { Check } from "typebox/value";
import { isAssistantMessage } from "./transcript/projection.ts";

const SERVER_SESSION_ENTRY_TYPE = "pi-server-session";

export interface ServerSessionState {
	cwd: string | undefined;
	model: { provider: string; id: string } | undefined;
	thinkingLevel: ThinkingLevel | undefined;
	invalidThinkingLevel: string | undefined;
	name: string | undefined;
	updatedAt: number;
}

export async function initializeServerSession(session: Session, cwd: string): Promise<void> {
	await session.appendCustomEntry(SERVER_SESSION_ENTRY_TYPE, { cwd });
}

export async function inspectServerSession(
	session: Session,
): Promise<{ branch: SessionTreeEntry[]; state: ServerSessionState; createdAt: number }> {
	const metadata = await session.getMetadata();
	const branch = await session.findEntriesOnBranch({ order: "oldestFirst" });
	const createdAt = parseCreatedAt(metadata.createdAt);
	return { branch, state: readServerSessionState(branch, createdAt), createdAt };
}

function isThinkingLevel(value: string): value is ThinkingLevel {
	return Check(ThinkingLevelSchema, value);
}

function readServerSessionState(entries: readonly SessionTreeEntry[], createdAt: number): ServerSessionState {
	let cwd: string | undefined;
	let model: ServerSessionState["model"];
	let thinkingLevel: ThinkingLevel | undefined;
	let invalidThinkingLevel: string | undefined;
	let name: string | undefined;
	let updatedAt = createdAt;
	for (const entry of entries) {
		const entryTime = parseEntryTimestamp(entry.timestamp, entry.id);
		updatedAt = Math.max(updatedAt, entryTime);
		if (entry.type === "custom" && entry.customType === SERVER_SESSION_ENTRY_TYPE) {
			if (
				typeof entry.data !== "object" ||
				entry.data === null ||
				!("cwd" in entry.data) ||
				typeof entry.data.cwd !== "string" ||
				entry.data.cwd.length === 0
			) {
				throw new Error(`Invalid server session metadata on entry ${entry.id}`);
			}
			cwd = entry.data.cwd;
		}
		if (entry.type === "model_change") model = { provider: entry.provider, id: entry.modelId };
		if (entry.type === "thinking_level_change") {
			if (isThinkingLevel(entry.thinkingLevel)) {
				thinkingLevel = entry.thinkingLevel;
				invalidThinkingLevel = undefined;
			} else {
				thinkingLevel = undefined;
				invalidThinkingLevel = entry.thinkingLevel;
			}
		}
		if (entry.type === "message" && isAssistantMessage(entry.message)) {
			model = { provider: entry.message.provider, id: entry.message.model };
		}
		if (entry.type === "session_info") name = entry.name?.trim() || undefined;
	}
	return { cwd, model, thinkingLevel, invalidThinkingLevel, name, updatedAt };
}

function parseCreatedAt(value: string): number {
	const parsed = Date.parse(value);
	if (!Number.isFinite(parsed) || parsed < 0) throw new Error(`Invalid session creation timestamp: ${value}`);
	return parsed;
}

function parseEntryTimestamp(value: string, entryId: string): number {
	const parsed = Date.parse(value);
	if (!Number.isFinite(parsed) || parsed < 0) {
		throw new Error(`Invalid timestamp on session entry ${entryId}: ${value}`);
	}
	return parsed;
}

import {
	AgentHarness,
	type AgentHarnessStreamOptions,
	type AgentHarnessTool,
	createBashTool,
	createEditTool,
	createReadTool,
	createWriteTool,
	type ExecutionToolContext,
	type Session,
} from "@earendil-works/pi-agent-core";
import type { NodeExecutionEnv } from "@earendil-works/pi-agent-core/node";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { ThinkingLevel } from "@earendil-works/pi-protocol";
import type { ModelRuntime } from "../core/model-runtime.ts";
import { mergeProviderAttributionHeaders } from "../core/provider-attribution.ts";
import type { SettingsManager } from "../core/settings-manager.ts";
import { buildSystemPrompt } from "../core/system-prompt.ts";
import { codingToolPrompts } from "../core/tools/tool-prompt.ts";

export interface CreateServerHarnessOptions {
	session: Session;
	modelRuntime: ModelRuntime;
	settingsManager: SettingsManager;
	model: Model<Api>;
	thinkingLevel: ThinkingLevel;
	env: NodeExecutionEnv;
	streamOptions: AgentHarnessStreamOptions;
	assertUsable(): void;
}

export function createServerHarness(options: CreateServerHarnessOptions): AgentHarness<ExecutionToolContext> {
	let harness: AgentHarness<ExecutionToolContext>;
	const readTool = createReadTool();
	const bashTool = createBashTool({
		commandPrefix: options.settingsManager.getShellCommandPrefix(),
		prepare: async (execution) => {
			options.assertUsable();
			const metadata = await options.session.getMetadata();
			execution.env.PI_SESSION_ID = metadata.id;
			execution.env.PI_SESSION_FILE =
				"path" in metadata && typeof metadata.path === "string" ? metadata.path : undefined;
			execution.env.PI_PROVIDER = harness.getModel().provider;
			execution.env.PI_MODEL = harness.getModel().id;
			execution.env.PI_REASONING_LEVEL = harness.getThinkingLevel();
		},
	});
	const tools: AgentHarnessTool<ExecutionToolContext>[] = [readTool, bashTool, createEditTool(), createWriteTool()];
	const toolNames = ["read", "bash", "edit", "write"] as const;
	const toolSnippets = Object.fromEntries(toolNames.map((name) => [name, codingToolPrompts[name].promptSnippet]));
	const promptGuidelines = [
		...codingToolPrompts.bash.promptGuidelines,
		...toolNames.filter((name) => name !== "bash").flatMap((name) => codingToolPrompts[name].promptGuidelines),
	];
	harness = new AgentHarness<ExecutionToolContext>({
		session: options.session,
		models: options.modelRuntime,
		model: options.model,
		thinkingLevel: options.thinkingLevel,
		tools,
		activeToolNames: [...toolNames],
		toolContext: { env: options.env },
		resources: {},
		steeringMode: options.settingsManager.getSteeringMode(),
		followUpMode: options.settingsManager.getFollowUpMode(),
		streamOptions: options.streamOptions,
		systemPrompt: async () => {
			options.assertUsable();
			const metadata = await options.session.getMetadata();
			const cwd = "cwd" in metadata && typeof metadata.cwd === "string" ? metadata.cwd : options.env.cwd;
			return buildSystemPrompt({
				cwd,
				selectedTools: [...toolNames],
				toolSnippets,
				promptGuidelines,
				contextFiles: [],
				skills: [],
			});
		},
	});
	harness.on("before_provider_request", (event) => {
		const merged = mergeProviderAttributionHeaders(event.model, options.settingsManager, event.sessionId);
		const headers = merged
			? Object.fromEntries(Object.entries(merged).filter((entry): entry is [string, string] => entry[1] !== null))
			: undefined;
		return { streamOptions: { headers } };
	});
	return harness;
}

import { type Api, clampThinkingLevel, type Model } from "@earendil-works/pi-ai";
import type { ModelMetadata, ModelRef, ThinkingLevel } from "@earendil-works/pi-protocol";
import { PiServerError, toProtocolModelMetadata } from "@earendil-works/pi-server";
import { DEFAULT_THINKING_LEVEL } from "../core/defaults.ts";
import type { ModelRuntime } from "../core/model-runtime.ts";
import type { SettingsManager } from "../core/settings-manager.ts";

export class ServerModelResolver {
	private readonly modelRuntime: ModelRuntime;
	private readonly settingsManager: SettingsManager;
	private defaultModel: ModelRef | undefined;
	private defaultThinkingLevel: ThinkingLevel | undefined;

	constructor(modelRuntime: ModelRuntime, settingsManager: SettingsManager) {
		this.modelRuntime = modelRuntime;
		this.settingsManager = settingsManager;
	}

	setDefaults(options: { model?: ModelRef; thinkingLevel?: ThinkingLevel }): void {
		this.defaultModel = options.model;
		this.defaultThinkingLevel = options.thinkingLevel;
	}

	async list(): Promise<ModelMetadata[]> {
		await this.modelRuntime.getAvailable();
		return this.modelRuntime
			.getModels()
			.map((model) => toProtocolModelMetadata(model, this.modelRuntime.hasConfiguredAuth(model.provider)));
	}

	async resolve(reference?: ModelRef): Promise<Model<Api>> {
		await this.modelRuntime.getAvailable();
		const requested = reference ?? this.defaultModel;
		if (requested) {
			const model = this.modelRuntime.getModel(requested.provider, requested.id);
			if (!model)
				throw new PiServerError("invalid_request", `Could not resolve ${requested.provider}/${requested.id}`);
			return this.requireAuthenticated(model);
		}
		const provider = this.settingsManager.getDefaultProvider();
		const id = this.settingsManager.getDefaultModel();
		const configured = provider && id ? this.modelRuntime.getModel(provider, id) : undefined;
		let model = configured && this.modelRuntime.hasConfiguredAuth(configured.provider) ? configured : undefined;
		if (!model) model = this.modelRuntime.getAvailableSnapshot()[0];
		if (!model) throw new PiServerError("invalid_request", "Could not resolve a default model");
		return this.requireAuthenticated(model);
	}

	resolveAvailable(reference: ModelRef): Model<Api> {
		const model = this.modelRuntime.getModel(reference.provider, reference.id);
		if (!model) throw new PiServerError("invalid_request", `Unknown model: ${reference.provider}/${reference.id}`);
		return this.requireAuthenticated(model);
	}

	private requireAuthenticated(model: Model<Api>): Model<Api> {
		if (!this.modelRuntime.hasConfiguredAuth(model.provider)) {
			throw new PiServerError("invalid_request", `Model is not authenticated: ${model.provider}/${model.id}`);
		}
		return model;
	}

	recoverThinkingLevel(model: Model<Api>, persisted?: ThinkingLevel): ThinkingLevel {
		return persisted === undefined ? this.resolveThinkingLevel(model) : clampThinkingLevel(model, persisted);
	}

	resolveThinkingLevel(model: Model<Api>, requested?: ThinkingLevel): ThinkingLevel {
		const fallback =
			this.defaultThinkingLevel ?? this.settingsManager.getDefaultThinkingLevel() ?? DEFAULT_THINKING_LEVEL;
		const level = requested ?? fallback;
		const clamped = clampThinkingLevel(model, level);
		if (requested !== undefined && clamped !== requested) {
			throw new PiServerError(
				"invalid_request",
				`Thinking level ${requested} is not supported by ${model.provider}/${model.id}`,
			);
		}
		return clamped;
	}
}

# @earendil-works/pi-server

Experimental. This package is under active development and may change or be removed without notice. Its APIs and behavior are not yet stable.

Transport-neutral session server for pi.

## Session server core

The package exports the `PiServer` session server and listener composition APIs.

```ts
import type { PiSessionBackend } from "@earendil-works/pi-server";
import { createUnixServer } from "@earendil-works/pi-server/unix";

const backend: PiSessionBackend = {
  async listSessions() {
    return storage.listSessions();
  },
  async listModels() {
    return modelRegistry.listModels();
  },
  async createSession(options) {
    return storage.createAndOpen(options);
  },
  async openSession(sessionId) {
    return storage.open(sessionId);
  },
};

const server = createUnixServer(backend, {
  token: process.env.PI_SERVER_TOKEN!,
  path: "/tmp/pi/server.sock",
});
await server.start();
```

`PiServer` composes transport listeners through the `PiServerListener` interface. The Unix submodule exports the `createUnixListener()` building block and `createUnixServer()` preset, keeping the common case concise without coupling the primary server to Unix sockets. The listener uses authenticated, length-prefixed CBOR messages from `@earendil-works/pi-protocol`.

## Transport testing

Custom transports can use `@earendil-works/pi-server/testing` for deterministic protocol conformance tests. It exports `createTestServer()`, `TestSessionBackend`, `ProtocolTestClient`, and the transport-neutral `WireChannel` contract. `connectUnixTestClient()` is provided for Unix transport tests.

## `pi-ai` protocol bridge

`@earendil-works/pi-ai` domain objects and `@earendil-works/pi-protocol` wire DTOs remain independent. This package owns their boundary and exports `toProtocolModelMetadata()`, `toProtocolAssistantMessage()`, `toProtocolUserMessage()`, and `toProtocolToolResultMessage()`.

The adapters reject invalid tool inputs, identifiers, timestamps, and mismatched tool results; `toProtocolToolResultMessage()` requires the original `ToolCall` so it can verify the association and convert its arguments itself. Diagnostic details are explicitly sanitized. Closed `pi-ai` unions are mapped exhaustively, and compile-time field manifests enumerate current `pi-ai` properties so additions require an explicit review. The protocol mirrors `pi-ai` vocabulary such as `toolCall` and `toolUse` where the semantics are identical. Protocol schemas enforce consistent lifecycle states, and tests encode adapter output through the runtime schemas so incompatible changes fail in the bridging package.

